{
  "id": "axiom",
  "name": "axiom",
  "version": "1.0.0",
  "description": "Cross-cutting verification gate. Confirms any stage artifact meets its criteria before the next stage begins. Implements the axiom protocol: recon → verify → exit-gate with retry-with-feedback.",
  "author": {
    "name": "Gabriel Castro",
    "email": "gabe@techworx.dev"
  },
  "skills": "./skills/",
  "agents": [
    "./subagents/axiom-recon.md",
    "./subagents/axiom-verifier.md",
    "./subagents/axiom-exit-gate.md"
  ]
}

{
  "id": "basis",
  "name": "basis",
  "version": "1.0.0",
  "description": "Meta-plugin for building new plugins. Scaffolds plugin directories, audits existing plugins for conformance to ecosystem schemas, and designs shared schema contracts. Replaces agent-plugin-builder.",
  "author": {
    "name": "Gabriel Castro",
    "email": "gabe@techworx.dev"
  },
  "skills": "./skills/",
  "agents": [
    "./subagents/basis-scaffolder.md",
    "./subagents/basis-auditor.md",
    "./subagents/basis-schema-designer.md"
  ]
}

