  "id": "vector",
  "name": "vector",
  "version": "1.0.0",
  "description": "Planning plugin. Decomposes specs into sequenced, bite-sized implementation plans with TDD steps, exact code, and commit messages. No TBDs. A developer with zero domain context can execute the plan mechanically.",
  "author": {
    "name": "Gabriel Castro",
    "email": "gabe@techworx.dev"
